function Tools({ disabled = false }: { disabled?: boolean }) {
  return (
    <>
      <IconButton
        aria-label="Add emoji"
        icon={<SmileyIcon size={20} aria-hidden="true" />}
        size="toolbar"
        disabled={disabled}
